for (const l of Object.keys(V3)) Object.assign(D[l], V3[l]);

let saved = null;
try { saved = localStorage.getItem('by_lang'); } catch { }
export let lang = D[saved] ? saved : 'en';

export function setLang(l) {
  if (!D[l]) return;
  lang = l;
  try { localStorage.setItem('by_lang', l); } catch { }
  applyDir();
}
export function applyDir() {
  if (typeof document === 'undefined') return;
  document.documentElement.lang = lang;
  document.documentElement.dir = lang === 'fa' ? 'rtl' : 'ltr';
}

/** t('key', {n: 3, x: 'name'}) — falls back to English, then to the key itself */
export function t(key, vars) {
  let s = (vars && vars.n === 1 && D[lang][key + '_1']) || D[lang][key] || D.en[key] || key;
  if (vars) for (const k in vars) s = s.replaceAll(`{${k}}`, k === 'n' ? num(vars[k]) : vars[k]);
  return s;
}
export const num = n => Number(n || 0).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US');
